+// zeroReader is an infinite source of zero bytes, used to inflate a zip entry
+// past the size cap without allocating the whole payload up front.
+type zeroReader struct{}
+
+func (zeroReader) Read(p []byte) (int, error) {
+	for i := range p {
+		p[i] = 0
+	}
+	return len(p), nil
+}
